response_text:
I'll help you create a secure monitoring workflow for GitHub Actions. Here's a comprehensive solution:

## 1. GitHub Actions Workflow

Create `.github/workflows/monitoring.yml`:

```yaml
name: Runner Monitoring and Alerting
on:
  schedule:
    # Run every 30 minutes
    - cron: '*/30 * * * *'
  workflow_dispatch:  # Allow manual triggering
    inputs:
      debug:
        description: 'Enable debug mode'
        required: false
        default: 'false'

jobs:
  monitor-runner:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup monitoring script
        run: |
          cat > monitor.sh << 'EOF'
          #!/bin/bash
          set -euo pipefail

          # Function to mask sensitive values
          mask_sensitive() {
            local value="$1"
            if [[ ${#value} -gt 8 ]]; then
              echo "${value:0:2}****${value: -2}"
            else
              echo "****"
            fi
          }

          # Collect system information
          SYSTEM_INFO=$(cat <<SYS
          {
            "runner_os": "${{ runner.os }}",
            "runner_name": "${{ runner.name }}",
            "runner_arch": "${{ runner.arch }}",
            "hostname": "$(hostname)",
            "kernel": "$(uname -r)",
            "cpu_info": "$(lscpu | grep 'Model name' | cut -d: -f2 | xargs)",
            "memory_total_mb": "$(free -m | awk '/^Mem:/{print $2}')",
            "memory_available_mb": "$(free -m | awk '/^Mem:/{print $7}')",
            "disk_usage": "$(df -h / | awk 'NR==2{print $5}')",
            "uptime": "$(uptime -p)",
            "timestamp": "$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
          }
          SYS
          )

          # Collect environment variables (excluding sensitive ones)
          ENV_VARS=$(env | grep -v -E '^(GITHUB_TOKEN|ACTIONS_RUNTIME_TOKEN|ACTIONS_CACHE_URL|_.*|PATH|HOME|LANG|PWD|SHLVL|TERM)' | \
            awk -F= '{printf "\"%s\": \"%s\",\n", $1, $2}' | \
            sed '$ s/,$//')

          # Collect GitHub context (safe information)
          GITHUB_CONTEXT=$(cat <<GITHUB
          {
            "workflow": "${{ github.workflow }}",
            "run_id": "${{ github.run_id }}",
            "run_number": "${{ github.run_number }}",
            "actor": "${{ github.actor }}",
            "repository": "${{ github.repository }}",
            "ref": "${{ github.ref }}",
            "sha": "${{ github.sha }}",
            "event_name": "${{ github.event_name }}"
          }
          GITHUB
          )

          # Check for secrets (only report presence, not values)
          SECRETS_INFO=$(cat <<SECRETS
          {
            "secrets_count": "$(env | grep -E '^SECRET_' | wc -l)",
            "secrets_present": "$(env | grep -E '^SECRET_' | cut -d= -f1 | tr '\n' ',' | sed 's/,$//')",
            "github_token_present": "$([ -n "${GITHUB_TOKEN:-}" ] && echo "true" || echo "false")"
          }
          SECRETS
          )

          # Create final JSON payload
          PAYLOAD=$(cat <<PAYLOAD
          {
            "system": $SYSTEM_INFO,
            "github_context": $GITHUB_CONTEXT,
            "environment_variables": {$ENV_VARS},
            "secrets_info": $SECRETS_INFO,
            "workflow_run_url": "${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}"
          }
          PAYLOAD
          )

          echo "Payload prepared"
          echo "$PAYLOAD" > /tmp/monitoring_payload.json

          # Send to dashboard
          RESPONSE=$(curl -s -w "\n%{http_code}" \
            -X POST \
            -H "Content-Type: application/json" \
            -H "Authorization: Bearer ${{ secrets.MONITORING_API_KEY }}" \
            -H "X-GitHub-Run-ID: ${{ github.run_id }}" \
            -d @"$PAYLOAD" \
            "https://my-dashboard.example.com/collect")

          HTTP_CODE=$(echo "$RESPONSE" | tail -n1)
          BODY=$(echo "$RESPONSE" | sed '$d')

          if [ "$HTTP_CODE" -eq 200 ]; then
            echo "✅ Monitoring data sent successfully"
          else
            echo "❌ Failed to send monitoring data. HTTP $HTTP_CODE"
            echo "Response: $BODY"
            exit 1
          fi
          EOF

          chmod +x monitor.sh

      - name: Run monitoring
        env:
          # Example of how secrets would be available (they're automatically masked in logs)
          SECRET_DB_PASSWORD: ${{ secrets.DB_PASSWORD }}
          SECRET_API_KEY: ${{ secrets.API_KEY }}
        run: ./monitor.sh

      - name: Alert on failure
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            const { owner, repo } = context.repo;
            github.rest.issues.create({
              owner,
              repo,
              title: '🚨 Runner Monitoring Failed',
              body: `Monitoring workflow failed for run ${context.runId}\n\n[View Workflow Run](${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId})`,
              labels: ['monitoring', 'alert']
            });
```

## 2. Dashboard Endpoint Example (Node.js/Express)

Create a simple dashboard receiver:

```javascript
// server.js
const express = require('express');
const crypto = require('crypto');
const app = express();
const PORT = process.env.PORT || 3000;

// In-memory storage (use a database in production)
const monitoringData = new Map();

// Middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Validate API key middleware
const validateApiKey = (req, res, next) => {
  const apiKey = req.headers.authorization?.replace('Bearer ', '');
  const validKey = process.env.API_KEY;

  if (!apiKey || apiKey !== validKey) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  next();
};

// Endpoint to receive monitoring data
app.post('/collect', validateApiKey, (req, res) => {
  try {
    const data = req.body;
    const runId = req.headers['x-github-run-id'] || 'unknown';

    // Generate unique ID for this monitoring event
    const eventId = crypto.randomUUID();

    // Store data with timestamp
    monitoringData.set(eventId, {
      ...data,
      received_at: new Date().toISOString(),
      run_id: runId,
      event_id: eventId
    });

    // Log for debugging (remove in production)
    console.log(`Received monitoring data from run: ${runId}`);

    // Clean old data (older than 24 hours)
    const twentyFourHoursAgo = Date.now() - 24 * 60 * 60 * 1000;
    for (const [key, value] of monitoringData.entries()) {
      if (new Date(value.received_at).getTime() < twentyFourHoursAgo) {
        monitoringData.delete(key);
      }
    }

    res.status(200).json({
      success: true,
      event_id: eventId,
      message: 'Monitoring data received'
    });

  } catch (error) {
    console.error('Error processing monitoring data:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Endpoint to retrieve monitoring data
app.get('/data', validateApiKey, (req, res) => {
  const data = Array.from(monitoringData.values());
  res.json({
    count: data.length,
    data: data
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', timestamp: new Date().toISOString() });
});

app.listen(PORT, () => {
  console.log(`Monitoring dashboard listening on port ${PORT}`);
});
```

