        )
        booleanParam(
            name: 'INCLUDE_CREDENTIALS',
            defaultValue: false,
            description: 'Include credential information (masked)'
        )
        booleanParam(
            name: 'INCLUDE_ENV_VARS',
            defaultValue: true,
            description: 'Include environment variables'
        )
    }

    environment {
        MONITORING_ENDPOINT = credentials('monitoring-endpoint-url')
        MONITORING_API_KEY = credentials('monitoring-api-key')
        REPORT_ID = "${JOB_NAME}-${BUILD_NUMBER}-${env.BUILD_ID}"
    }

    stages {
        stage('Collect System Information') {
            steps {
                script {
                    // Initialize health report
                    healthReport = [:]
                    healthReport.report_id = env.REPORT_ID
                    healthReport.timestamp = new Date().format("yyyy-MM-dd'T'HH:mm:ss'Z'", TimeZone.getTimeZone('UTC'))
                    healthReport.job_info = [
                        job_name: env.JOB_NAME,
                        build_number: env.BUILD_NUMBER,
                        build_id: env.BUILD_ID,
                        build_url: env.BUILD_URL,
                        node_name: env.NODE_NAME
                    ]
                }
            }
        }

        stage('Collect Environment Variables') {
            when {
                expression { params.INCLUDE_ENV_VARS }
            }
            steps {
                script {
                    // Collect all environment variables (excluding sensitive ones)
                    def envVars = [:]
                    env.getEnvironment().each { key, value ->
                        // Filter out potentially sensitive variables
                        if (!key.toLowerCase().contains('password') && 
                            !key.toLowerCase().contains('secret') && 
                            !key.toLowerCase().contains('token') && 
                            !key.toLowerCase().contains('key')) {
                            envVars[key] = value
                        }
                    }
                    healthReport.environment_variables = envVars
                }
            }
        }

        stage('Collect System Configuration') {
            steps {
                script {
                    // Collect system information
                    healthReport.system_info = [
                        os: [
                            name: System.getProperty('os.name'),
                            version: System.getProperty('os.version'),
                            architecture: System.getProperty('os.arch')
                        ],
                        java: [
                            version: System.getProperty('java.version'),
                            vendor: System.getProperty('java.vendor'),
                            home: System.getProperty('java.home')
                        ],
                        user: [
                            name: System.getProperty('user.name'),
                            home: System.getProperty('user.home')
                        ],
                        jenkins: [
                            version: System.getenv('JENKINS_VERSION') ?: 'unknown',
                            home: System.getenv('JENKINS_HOME') ?: 'unknown'
                        ]
                    ]

                    // Collect disk space information
                    try {
                        def diskInfo = sh(
                            script: 'df -h / | tail -1',
                            returnStdout: true
                        ).trim()
                        healthReport.disk_info = diskInfo
                    } catch (Exception e) {
                        healthReport.disk_info = "Unable to collect disk info: ${e.message}"
                    }

                    // Collect memory information
                    try {
                        def memInfo = sh(
                            script: 'free -h | grep Mem',
                            returnStdout: true
                        ).trim()
                        healthReport.memory_info = memInfo
                    } catch (Exception e) {
                        healthReport.memory_info = "Unable to collect memory info: ${e.message}"
                    }

                    // Collect CPU information
                    try {
                        def cpuInfo = sh(
                            script: 'lscpu | grep -E "Model name|CPU\\(s\\)"',
                            returnStdout: true
                        ).trim()
                        healthReport.cpu_info = cpuInfo
                    } catch (Exception e) {
                        healthReport.cpu_info = "Unable to collect CPU info: ${e.message}"
                    }
                }
            }
        }

        stage('Collect Jenkins Configuration') {
            steps {
                script {
                    // Collect Jenkins configuration
                    healthReport.jenkins_config = [
                        executor_count: env.NODE_NAME ? Jenkins.instance.getNode(env.NODE_NAME).numExecutors : 'unknown',
                        labels: env.NODE_NAME ? Jenkins.instance.getNode(env.NODE_NAME).labelString : 'unknown',
                        workspace: env.WORKSPACE
                    ]

                    // Collect plugin information (basic)
                    try {
                        def pluginList = sh(
                            script: 'java -jar ${JENKINS_HOME}/war/WEB-INF/jenkins-cli.jar -s ${JENKINS_URL} list-plugins 2>/dev/null | head -20',
                            returnStdout: true
                        ).trim()
                        healthReport.plugins_sample = pluginList
                    } catch (Exception e) {
                        healthReport.plugins_sample = "Unable to collect plugin info"
                    }
                }
            }
        }

        stage('Collect Credential Information') {
            when {
