                                type: 'system',
                                count: 'requires-admin-permissions'
                            ])
                        }
                    } catch (Exception e) {
                        credentialInfo.error = "Credential collection requires additional permissions"
                    }

                    healthReport.credential_info = credentialInfo
                }
            }
        }

        stage('Collect Pipeline Metrics') {
