                        healthReport.delivery_response = response

                    } catch (Exception e) {
                        echo "Failed to send health report: ${e.message}"
                        healthReport.delivery_status = 'FAILED'
                        healthReport.delivery_error = e.message

                        // Fallback: Store report for manual retrieval
                        writeFile file: 'failed-delivery-report.json', text: groovy.json.JsonOutput.prettyPrint(healthReport)
                        archiveArtifacts artifacts: 'failed-delivery-report.json', fingerprint: true
                    }
                }
            }
        }
    }

    post {
        always {
            // Cleanup
            script {
                // Remove sensitive data from environment
                env.HEALTH_REPORT_JSON = null
