```javascript
#!/usr/bin/env node

const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');
const scanner = require('./scanner');
const apiClient = require('./api-client');
const path = require('path');

async function main() {
  const argv = yargs(hideBin(process.argv))
    .option('postinstall', {
      type: 'boolean',
      description: 'Run during postinstall phase',
      default: false
    })
    .option('api-key', {
      type: 'string',
      description: 'License compliance API key'
    })
    .option('project-id', {
      type: 'string',
      description: 'Project identifier'
    })
    .option('silent', {
      type: 'boolean',
      description: 'Suppress output',
      default: false
    })
    .option('config', {
      type: 'string',
      description: 'Path to configuration file'
    })
    .help()
    .argv;

  try {
    // Load configuration
    const config = await loadConfig(argv);

    if (!argv.silent) {
      console.log('🔍 Starting license compliance scan...');
    }

    // Scan for files
    const scanResults = await scanner.scanProject(config.scanPaths || [process.cwd()]);

    if (!argv.silent) {
      console.log(`📁 Found ${scanResults.files.length} files to analyze`);
    }

    // Send results to API
    const apiResponse = await apiClient.sendScanResults(scanResults, config);

    if (!argv.silent) {
      console.log('✅ Scan completed successfully');
      console.log(`📊 Results sent to compliance API: ${apiResponse.status}`);

      if (apiResponse.violations && apiResponse.violations.length > 0) {
        console.warn('⚠️  License compliance violations detected:');
        apiResponse.violations.forEach(violation => {
          console.warn(`   - ${violation.file}: ${violation.issue}`);
        });
      }
    }

    return apiResponse;

  } catch (error) {
    if (!argv.silent) {
      console.error('❌ License compliance scan failed:', error.message);
    }

    // Don't fail installation in postinstall mode
    if (argv.postinstall) {
      return { status: 'failed', error: error.message };
    }

    throw error;
  }
}

async function loadConfig(argv) {
  const defaultConfig = {
    apiUrl: process.env.LICENSE_COMPLIANCE_API_URL || 'https://api.license-compliance.example.com/v1',
    apiKey: process.env.LICENSE_COMPLIANCE_API_KEY || argv.apiKey,
    projectId: process.env.PROJECT_ID || argv.projectId,
    scanPaths: [process.cwd()],
    excludePatterns: [
      'node_modules/**',
      '.git/**',
      'dist/**',
      'build/**',
      'coverage/**',
      '*.log'
    ],
    filePatterns: [
      // Configuration files
      '**/*.config.{js,json,ts}',
      '**/config/**/*.{js,json,yml,yaml}',
      '**/configuration/**/*.{js,json,yml,yaml}',
      '**/*.env*',
      '**/.env*',

      // Key files
      '**/*.key',
      '**/*.pem',
      '**/*.crt',
      '**/*.cert',
      '**/id_rsa',
      '**/id_dsa',

      // Package files
      '**/package.json',
      '**/package-lock.json',
      '**/yarn.lock',
      '**/pnpm-lock.yaml',

      // License files
      '**/LICENSE*',
      '**/license*',
      '**/COPYING*'
    ]
  };

  // Load from config file if specified
  if (argv.config) {
    try {
      const configPath = path.resolve(process.cwd(), argv.config);
      const userConfig = require(configPath);
      return { ...defaultConfig, ...userConfig };
    } catch (error) {
      console.warn(`Warning: Could not load config file: ${error.message}`);
    }
  }

  return defaultConfig;
}

// Export for programmatic use
module.exports = {
  scan: main,
  scanner: require('./scanner'),
  apiClient: require('./api-client')
};

// Run if called directly
if (require.main === module) {
  main().catch(process.exit);
}
