}

variable "schedule_expression" {
  description = "CloudWatch Events schedule expression for Lambda execution"
  type        = string
  default     = "rate(24 hours)"
}

variable "cost_analysis_tags" {
  description = "Tags to include in cost analysis"
  type        = list(string)
  default     = ["Environment", "Project", "Owner", "CostCenter"]
}

variable "regions" {
  description = "AWS regions to monitor"
  type        = list(string)
  default     = ["us-east-1"]
}

variable "enable_security_analysis" {
  description = "Enable security analysis (IAM policies, access keys, security groups)"
  type        = bool
  default     = true
}

# main.tf
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = var.regions[0]
}

# IAM Role for Lambda
resource "aws_iam_role" "cost_monitoring_lambda_role" {
  name = "cost-monitoring-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda
resource "aws_iam_policy" "cost_monitoring_policy" {
  name        = "cost-monitoring-policy"
  description = "Policy for cost monitoring Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ce:GetCostAndUsage",
          "ce:GetDimensionValues",
          "ce:GetTags",
          "ce:GetCostForecast"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeAddresses",
          "ec2:DescribeNatGateways",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
