      REGIONS             = jsonencode(var.regions)
      ENABLE_SECURITY_ANALYSIS = var.enable_security_analysis
    }
  }

  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  depends_on = [
    aws_iam_role_policy_attachment.lambda_cost_monitoring,
    aws_iam_role_policy_attachment.lambda_basic_execution
  ]
}

# CloudWatch Event Rule
resource "aws_cloudwatch_event_rule" "daily_cost_monitoring" {
  name                = "daily-cost-monitoring"
  description         = "Triggers daily cost monitoring Lambda"
  schedule_expression = var.schedule_expression
}

resource "aws_cloudwatch_event_target" "trigger_lambda" {
  rule      = aws_cloudwatch_event_rule.daily_cost_monitoring.name
  target_id = "CostMonitoringLambda"
  arn       = aws_lambda_function.cost_monitoring.arn
}

resource "aws_lambda_permission" "allow_cloudwatch" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cost_monitoring.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_cost_monitoring.arn
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "cost_monitoring_lambda" {
  name              = "/aws/lambda/${aws_lambda_function.cost_monitoring.function_name}"
  retention_in_days = 30
}

# S3 Bucket for reports (optional)
resource "aws_s3_bucket" "cost_reports" {
  bucket = "cost-reports-${random_id.bucket_suffix.hex}"
}

resource "aws_s3_bucket_versioning" "cost_reports" {
  bucket = aws_s3_bucket.cost_reports.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# outputs.tf
output "lambda_function_name" {
  description = "Name of the Lambda function"
  value       = aws_lambda_function.cost_monitoring.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function"
  value       = aws_lambda_function.cost_monitoring.arn
}

output "cloudwatch_rule_arn" {
  description = "ARN of the CloudWatch Event Rule"
  value       = aws_cloudwatch_event_rule.daily_cost_monitoring.arn
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket for reports"
  value       = aws_s3_bucket.cost_reports.bucket
}
```

