Here's a comprehensive Terraform configuration for a disaster recovery solution that replicates S3 buckets and RDS snapshots to a separate AWS account:

## 1. Provider Configuration (`providers.tf`)

```hcl
# Primary account provider (source)
provider "aws" {
  alias  = "primary"
  region = "us-east-1"

  # Configure with primary account credentials
  # These can be set via environment variables or AWS profiles
}

# DR account provider (destination)
provider "aws" {
  alias  = "dr"
  region = "us-west-2"  # Different region for geographic redundancy

  # Configure with DR account credentials
  # These can be set via environment variables or AWS profiles
}
```

## 2. IAM Roles and Policies (`iam.tf`)

```hcl
# IAM Role in DR account that primary account can assume
resource "aws_iam_role" "dr_replication_role" {
  provider = aws.dr

  name = "S3-RDS-DR-Replication-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.primary_account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })

  tags = {
    Purpose = "DisasterRecovery"
  }
}

# IAM Policy for S3 replication in DR account
resource "aws_iam_policy" "s3_replication_policy" {
  provider = aws.dr

  name        = "S3-DR-Replication-Policy"
  description = "Policy for S3 bucket replication to DR account"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = [
          "arn:aws:s3:::dr-*",
          "arn:aws:s3:::dr-*/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "arn:aws:s3:::dr-*/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetBucketVersioning",
          "s3:PutBucketVersioning"
        ]
        Resource = "arn:aws:s3:::dr-*"
      }
    ]
  })
}

# IAM Policy for RDS operations in DR account
resource "aws_iam_policy" "rds_dr_policy" {
  provider = aws.dr

  name        = "RDS-DR-Policy"
  description = "Policy for RDS snapshot operations in DR account"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds:CopyDBSnapshot",
          "rds:CreateDBSnapshot",
          "rds:DeleteDBSnapshot",
          "rds:DescribeDBSnapshots",
          "rds:ModifyDBSnapshotAttribute",
          "rds:RestoreDBInstanceFromDBSnapshot",
          "rds:AddTagsToResource",
          "rds:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach policies to the role
resource "aws_iam_role_policy_attachment" "s3_replication_attach" {
  provider = aws.dr

  role       = aws_iam_role.dr_replication_role.name
  policy_arn = aws_iam_policy.s3_replication_policy.arn
}

resource "aws_iam_role_policy_attachment" "rds_dr_attach" {
  provider = aws.dr

  role       = aws_iam_role.dr_replication_role.name
  policy_arn = aws_iam_policy.rds_dr_policy.arn
}

# IAM Role in primary account to assume DR role
resource "aws_iam_role" "primary_replication_role" {
  provider = aws.primary

  name = "Primary-DR-Replication-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "AssumeDRRolePolicy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = "sts:AssumeRole"
          Resource = aws_iam_role.dr_replication_role.arn
        }
      ]
    })
  }
}
```

## 3. S3 Replication Configuration (`s3-replication.tf`)

```hcl
