  region = var.aws_region
}

# Secure S3 bucket for Terraform state with encryption
resource "aws_s3_bucket" "tf_state" {
  bucket = "${var.project_name}-tf-state-${random_id.suffix.hex}"

  tags = {
    Name        = "Terraform State"
    Environment = var.environment
    Compliance  = "encrypted"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_encryption" {
  bucket = aws_s3_bucket.tf_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "state_versioning" {
  bucket = aws_s3_bucket.tf_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state_block" {
  bucket = aws_s3_bucket.tf_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Lambda function for compliance checking WITHOUT secret extraction
