  bucket = aws_s3_bucket.tf_state.id
  key    = "terraform.tfstate"

  # Example tagging to prevent Lambda from reading secret-containing objects
  tags = {
    Secret = "true"
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

# variables.tf
