## Secure Lambda Function (Python):

```python
# lambda_function.py
import json
import boto3
import os
from datetime import datetime
import urllib3

s3_client = boto3.client('s3')
http = urllib3.PoolManager()

def lambda_handler(event, context):
    """Check compliance without extracting secrets"""

    # Configuration
    state_bucket = os.environ['STATE_BUCKET']
    audit_api_url = os.environ['AUDIT_API_URL']

    try:
        # Get state file (metadata only approach)
        response = s3_client.get_object(
            Bucket=state_bucket,
            Key='terraform.tfstate'
        )

        state_data = json.loads(response['Body'].read().decode('utf-8'))

        # Extract NON-SENSITIVE compliance information
        compliance_report = {
            'timestamp': datetime.utcnow().isoformat(),
            'environment': os.environ['ENVIRONMENT'],
            'resource_count': len(state_data.get('resources', [])),
            'terraform_version': state_data.get('terraform_version', 'unknown'),
            'resource_types': extract_resource_types(state_data),
            'compliance_checks': perform_compliance_checks(state_data)
        }

        # Send to audit platform (without secrets)
        send_audit_report(compliance_report, audit_api_url)

        return {
            'statusCode': 200,
            'body': json.dumps('Compliance check completed successfully')
        }

    except Exception as e:
        print(f"Error: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps(f'Error: {str(e)}')
        }

def extract_resource_types(state_data):
    """Extract resource types without sensitive data"""
    resource_types = set()
    for resource in state_data.get('resources', []):
        if 'type' in resource:
            resource_types.add(resource['type'])
    return list(resource_types)

def perform_compliance_checks(state_data):
    """Perform compliance checks without accessing secrets"""
    checks = {
        'encryption_enabled': check_encryption(state_data),
        'public_access_blocked': check_public_access(state_data),
        'logging_enabled': check_logging(state_data),
        'tags_present': check_required_tags(state_data)
    }
    return checks

def check_encryption(state_data):
    """Check if resources have encryption enabled"""
    # Implementation that checks resource attributes without reading secrets
    pass

def send_audit_report(report, api_url):
    """Send compliance report to audit platform"""
    headers = {'Content-Type': 'application/json'}
    response = http.request(
        'POST',
        api_url,
        body=json.dumps(report).encode('utf-8'),
        headers=headers
    )
    return response.status
