    def log(self, message, level="INFO"):
        print(f"[{level}] {message}")

    def collect_runner_info(self):
        """Collect information about the GitHub Actions runner"""
        self.log("Collecting runner information...")

        # Check if running in GitHub Actions
        self.results['environment']['github_actions'] = 'GITHUB_ACTIONS' in os.environ

        # Get runner metadata
        runner_info = {}

        # GitHub Actions environment variables
        env_vars = [
            'GITHUB_WORKFLOW', 'GITHUB_RUN_ID', 'GITHUB_RUN_NUMBER',
            'GITHUB_ACTION', 'GITHUB_ACTIONS', 'GITHUB_ACTOR',
            'GITHUB_REPOSITORY', 'GITHUB_EVENT_NAME', 'GITHUB_WORKSPACE',
            'GITHUB_SHA', 'GITHUB_REF', 'GITHUB_HEAD_REF', 'GITHUB_BASE_REF',
            'RUNNER_NAME', 'RUNNER_OS', 'RUNNER_TEMP', 'RUNNER_TOOL_CACHE'
        ]

        for var in env_vars:
            if var in os.environ:
                runner_info[var] = os.environ[var]

        self.results['runner_info'] = runner_info

        # Get system information
        try:
            runner_info['hostname'] = subprocess.check_output(['hostname'], text=True).strip()
        except:
            runner_info['hostname'] = 'unknown'

        # Check for self-hosted runner indicators
        runner_info['self_hosted'] = 'RUNNER_NAME' in os.environ and not os.environ.get('RUNNER_NAME', '').startswith('Hosted Agent')

        return runner_info

    def analyze_github_token_permissions(self):
        """Analyze GITHUB_TOKEN permissions and scope"""
        self.log("Analyzing GITHUB_TOKEN permissions...")

        token_permissions = {}

        # Check if GITHUB_TOKEN is available
        if 'GITHUB_TOKEN' not in os.environ:
            self.log("GITHUB_TOKEN not found in environment", "WARNING")
            return token_permissions

        token = os.environ['GITHUB_TOKEN']

        # Try to get token information via GitHub API
        headers = {
            'Authorization': f'token {token}',
            'Accept': 'application/vnd.github.v3+json'
        }

        try:
            # Get authenticated user
            response = requests.get('https://api.github.com/user', headers=headers, timeout=10)
            if response.status_code == 200:
                user_info = response.json()
                token_permissions['authenticated_user'] = user_info.get('login')

            # Get token scopes from response headers
            if 'X-OAuth-Scopes' in response.headers:
                scopes = response.headers['X-OAuth-Scopes'].split(', ')
                token_permissions['scopes'] = scopes

            # Check repository permissions
            repo = os.environ.get('GITHUB_REPOSITORY')
            if repo:
                response = requests.get(
                    f'https://api.github.com/repos/{repo}',
                    headers=headers,
                    timeout=10
                )
                if response.status_code == 200:
                    repo_info = response.json()
                    token_permissions['repo_permissions'] = repo_info.get('permissions', {})

            # Check organization access if applicable
            if repo and '/' in repo:
                org = repo.split('/')[0]
                response = requests.get(
                    f'https://api.github.com/orgs/{org}',
                    headers=headers,
                    timeout=10
                )
                if response.status_code == 200:
                    token_permissions['org_access'] = True

        except Exception as e:
            self.log(f"Error checking token permissions: {e}", "ERROR")

        self.results['permissions']['github_token'] = token_permissions
        return token_permissions

    def extract_secrets_from_environment(self):
        """Extract secrets from environment variables"""
        self.log("Extracting secrets from environment...")

        secrets = {}

        # Look for common secret patterns in environment
        secret_patterns = [
            r'(?i)(token|key|secret|password|passwd|pwd|credential)',
            r'(?i)(aws_|azure_|gcp_|google_)',
            r'(?i)(api[_-]?key)',
            r'(?i)(private[_-]?key)',
            r'(?i)(access[_-]?token)',
            r'(?i)(bearer)'
        ]

        for key, value in os.environ.items():
            for pattern in secret_patterns:
                if re.search(pattern, key) and value:
                    # Don't store actual values in report for security
                    secrets[key] = {
                        'present': True,
                        'length': len(value),
                        'first_chars': value[:4] + '...' if len(value) > 4 else '***'
                    }
                    break

        self.results['secrets']['environment'] = secrets
        return secrets

    def analyze_workflow_files(self):
        """Analyze workflow files for secrets usage"""
        self.log("Analyzing workflow files...")

        workflows = {}
        workspace = os.environ.get('GITHUB_WORKSPACE', '.')

        # Look for workflow files
