                                'size': len(content)
                            }

                    except Exception as e:
                        self.log(f"Error parsing {workflow_file}: {e}", "WARNING")

        self.results['secrets']['workflows'] = workflows
        return workflows

    def extract_secrets_from_yaml(self, yaml_data):
        """Recursively extract secret references from YAML"""
        secrets = []

        if isinstance(yaml_data, dict):
