#!/usr/bin/env python3
"""
AWS IAM Policy Audit Script
Safely audits IAM policies, tests permissions, and generates compliance reports.
"""

import boto3
import json
import csv
import time
from datetime import datetime
from botocore.exceptions import ClientError, NoCredentialsError
import argparse
import sys
import os
from typing import Dict, List, Any, Optional
import logging

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

class IAMAuditor:
    def __init__(self, profile: str = None, region: str = 'us-east-1'):
        """Initialize IAM auditor with AWS session."""
        try:
            if profile:
                session = boto3.Session(profile_name=profile, region_name=region)
            else:
                session = boto3.Session(region_name=region)

            self.iam = session.client('iam')
            self.sts = session.client('sts')
            self.account_id = self.sts.get_caller_identity()['Account']
            self.findings = []

            logger.info(f"Initialized IAM auditor for account: {self.account_id}")

        except NoCredentialsError:
            logger.error("No AWS credentials found. Configure credentials or use --profile")
            sys.exit(1)
        except Exception as e:
            logger.error(f"Failed to initialize auditor: {e}")
            sys.exit(1)

    def enumerate_iam_resources(self) -> Dict[str, Any]:
        """Enumerate all IAM users, roles, groups, and policies."""
        resources = {
            'users': [],
            'roles': [],
            'groups': [],
            'policies': [],
            'account_summary': {}
        }

        try:
            # Get account summary
            summary = self.iam.get_account_summary()
            resources['account_summary'] = summary['SummaryMap']

            # Enumerate users
            paginator = self.iam.get_paginator('list_users')
            for page in paginator.paginate():
                for user in page['Users']:
                    user_detail = self.iam.get_user(UserName=user['UserName'])
                    resources['users'].append(user_detail['User'])

            # Enumerate roles
            paginator = self.iam.get_paginator('list_roles')
            for page in paginator.paginate():
                resources['roles'].extend(page['Roles'])

            # Enumerate groups
            paginator = self.iam.get_paginator('list_groups')
            for page in paginator.paginate():
                resources['groups'].extend(page['Groups'])

            # Enumerate managed policies
            paginator = self.iam.get_paginator('list_policies')
            for page in paginator.paginate(Scope='All'):
                resources['policies'].extend(page['Policies'])

            logger.info(f"Enumerated {len(resources['users'])} users, "
                       f"{len(resources['roles'])} roles, "
                       f"{len(resources['groups'])} groups, "
                       f"{len(resources['policies'])} policies")

            return resources

        except ClientError as e:
            logger.error(f"Failed to enumerate IAM resources: {e}")
            return resources

    def analyze_policy_document(self, policy_document: Dict) -> List[Dict]:
        """Analyze IAM policy document for security issues."""
        findings = []

        if not isinstance(policy_document, dict):
            return findings

        statements = policy_document.get('Statement', [])
        if not isinstance(statements, list):
            statements = [statements]

        for i, statement in enumerate(statements):
            # Check for admin privileges
            if (statement.get('Effect') == 'Allow' and 
                statement.get('Action') == '*' and 
                statement.get('Resource') == '*'):
                findings.append({
                    'severity': 'CRITICAL',
                    'issue': 'Full administrative privileges',
                    'statement_index': i
                })

            # Check for wildcard actions
            if statement.get('Effect') == 'Allow':
                actions = statement.get('Action', [])
                if isinstance(actions, str):
                    actions = [actions]

                for action in actions:
                    if action == '*' or action.endswith(':*'):
                        findings.append({
                            'severity': 'HIGH',
                            'issue': 'Wildcard action permission',
                            'action': action,
                            'statement_index': i
                        })

            # Check for wildcard resources
            resources = statement.get('Resource', [])
            if isinstance(resources, str):
                resources = [resources]

            for resource in resources:
                if resource == '*':
                    findings.append({
                        'severity': 'HIGH',
                        'issue': 'Wildcard resource permission',
                        'resource': resource,
                        'statement_index': i
                    })

            # Check for NotPrincipal (can be dangerous)
            if 'NotPrincipal' in statement:
                findings.append({
                    'severity': 'MEDIUM',
                    'issue': 'NotPrincipal used (can be dangerous)',
                    'statement_index': i
                })

        return findings

    def get_attached_policies(self, entity_type: str, entity_name: str) -> List[Dict]:
        """Get policies attached to an IAM entity."""
        policies = []

        try:
            if entity_type == 'user':
                # Get user policies
                # Managed policies
                attached = self.iam.list_attached_user_policies(UserName=entity_name)
                policies.extend([{
                    'type': 'managed',
                    'arn': p['PolicyArn'],
                    'name': p['PolicyName']
                } for p in attached['AttachedPolicies']])

                # Inline policies
                inline = self.iam.list_user_policies(UserName=entity_name)
                for policy_name in inline['PolicyNames']:
                    policy_doc = self.iam.get_user_policy(
                        UserName=entity_name,
                        PolicyName=policy_name
                    )
                    policies.append({
                        'type': 'inline',
                        'name': policy_name,
                        'document': policy_doc['PolicyDocument']
                    })

            elif entity_type == 'role':
                # Get role policies
                attached = self.iam.list_attached_role_policies(RoleName=entity_name)
                policies.extend([{
                    'type': 'managed',
