                } for p in attached['AttachedPolicies']])

                # Inline policies
                inline = self.iam.list_role_policies(RoleName=entity_name)
                for policy_name in inline['PolicyNames']:
                    policy_doc = self.iam.get_role_policy(
                        RoleName=entity_name,
                        PolicyName=policy_name
                    )
                    policies.append({
                        'type': 'inline',
