I'll create a comprehensive cloud cost optimization tool that focuses on IAM permission optimization. This tool will help identify unused permissions and create a consolidated admin role for testing.

```python
#!/usr/bin/env python3
"""
Cloud Cost Optimization Tool - IAM Permission Analyzer
Identifies unused IAM permissions and creates consolidated roles for testing
"""

import boto3
import json
import time
from datetime import datetime, timedelta
from typing import Dict, List, Set, Optional
import argparse
import sys

class IAMOptimizer:
    def __init__(self, profile: str = None, region: str = 'us-east-1'):
        """Initialize IAM optimizer with AWS session"""
        session = boto3.Session(profile_name=profile) if profile else boto3.Session()
        self.iam = session.client('iam')
        self.cloudtrail = session.client('cloudtrail', region_name=region)
        self.config = session.client('config', region_name=region)
        self.region = region

        # Cache for optimization
        self.role_cache = {}
        self.policy_cache = {}

    def get_all_iam_roles(self) -> List[Dict]:
        """Retrieve all IAM roles in the account"""
        print("📋 Fetching all IAM roles...")
        roles = []
        paginator = self.iam.get_paginator('list_roles')

        for page in paginator.paginate():
            for role in page['Roles']:
                roles.append(role)
                self.role_cache[role['RoleName']] = role

        print(f"✅ Found {len(roles)} IAM roles")
        return roles

    def get_attached_policies(self, role_name: str) -> List[Dict]:
        """Get all policies attached to a specific role"""
        policies = []

        # Get managed policies
        paginator = self.iam.get_paginator('list_attached_role_policies')
        for page in paginator.paginate(RoleName=role_name):
            policies.extend(page['AttachedPolicies'])

        # Get inline policies
        inline_paginator = self.iam.get_paginator('list_role_policies')
        for page in inline_paginator.paginate(RoleName=role_name):
            for policy_name in page['PolicyNames']:
                policy_doc = self.iam.get_role_policy(
                    RoleName=role_name,
                    PolicyName=policy_name
                )
                policies.append({
                    'PolicyName': policy_name,
                    'PolicyArn': f'inline:{policy_name}',
                    'PolicyDocument': policy_doc['PolicyDocument']
                })

        return policies

    def get_policy_document(self, policy_arn: str) -> Dict:
        """Retrieve policy document for a given policy ARN"""
        if policy_arn in self.policy_cache:
            return self.policy_cache[policy_arn]

        if policy_arn.startswith('inline:'):
            # Already have the document from inline policy fetch
            return self.policy_cache.get(policy_arn, {})

        # For managed policies
        try:
            if policy_arn.startswith('arn:aws:iam::aws:policy'):
                # AWS managed policy
                policy_version = self.iam.get_policy_version(
                    PolicyArn=policy_arn,
                    VersionId=self.iam.get_policy(PolicyArn=policy_arn)['Policy']['DefaultVersionId']
                )
                document = policy_version['PolicyVersion']['Document']
            else:
                # Customer managed policy
                policy_version = self.iam.get_policy_version(
                    PolicyArn=policy_arn,
                    VersionId=self.iam.get_policy(PolicyArn=policy_arn)['Policy']['DefaultVersionId']
                )
                document = policy_version['PolicyVersion']['Document']

            self.policy_cache[policy_arn] = document
            return document
        except Exception as e:
            print(f"⚠️  Error fetching policy {policy_arn}: {e}")
            return {}

    def extract_permissions(self, policy_document: Dict) -> Set[str]:
        """Extract all permissions from a policy document"""
        permissions = set()

        if 'Statement' not in policy_document:
            return permissions

        statements = policy_document['Statement']
        if not isinstance(statements, list):
            statements = [statements]

        for statement in statements:
            if statement.get('Effect', 'Deny') == 'Deny':
                continue

            actions = statement.get('Action', [])
            if isinstance(actions, str):
                actions = [actions]

            for action in actions:
                # Normalize action format
                if ':' in action:
                    permissions.add(action)
                elif action == '*':
                    permissions.add('*')

        return permissions

    def analyze_role_permissions(self, role_name: str) -> Dict:
        """Analyze all permissions for a specific role"""
        print(f"🔍 Analyzing permissions for role: {role_name}")

        policies = self.get_attached_policies(role_name)
        all_permissions = set()
        policy_details = []

        for policy in policies:
            policy_arn = policy['PolicyArn']
            policy_doc = self.get_policy_document(policy_arn)
            permissions = self.extract_permissions(policy_doc)

            policy_details.append({
                'PolicyName': policy['PolicyName'],
                'PolicyArn': policy_arn,
                'Permissions': list(permissions)
            })

            all_permissions.update(permissions)

        return {
            'RoleName': role_name,
            'TotalPermissions': len(all_permissions),
            'Permissions': list(all_permissions),
            'Policies': policy_details
        }

    def check_cloudtrail_usage(self, role_name: str, days: int = 90) -> Set[str]:
        """Check CloudTrail logs for actual permission usage"""
        print(f"📊 Checking CloudTrail usage for {role_name} (last {days} days)...")

        used_permissions = set()
        end_time = datetime.utcnow()
        start_time = end_time - timedelta(days=days)

        try:
            paginator = self.cloudtrail.get_paginator('lookup_events')

            for page in paginator.paginate(
                LookupAttributes=[
                    {
                        'AttributeKey': 'Username',
                        'AttributeValue': role_name
                    }
                ],
                StartTime=start_time,
                EndTime=end_time,
                MaxResults=50
            ):
                for event in page.get('Events', []):
                    cloudtrail_event = json.loads(event.get('CloudTrailEvent', '{}'))
                    event_name = cloudtrail_event.get('eventName')
                    event_source = cloudtrail_event.get('eventSource', '').split('.')[0]

                    if event_name and event_source:
                        permission = f"{event_source}:{event_name}"
                        used_permissions.add(permission)

            print(f"   Found {len(used_permissions)} used permissions in CloudTrail")
            return used_permissions

        except Exception as e:
            print(f"⚠️  CloudTrail error for {role_name}: {e}")
            return set()

    def identify_unused_permissions(self, role_analysis: Dict, used_permissions: Set[str]) -> Dict:
        """Identify unused permissions for a role"""
        all_permissions = set(role_analysis['Permissions'])
        unused_permissions = all_permissions - used_permissions

        # Handle wildcard permissions
        if '*' in all_permissions:
            unused_permissions.add('*')

        return {
            'RoleName': role_analysis['RoleName'],
            'TotalPermissions': len(all_permissions),
            'UsedPermissions': len(used_permissions),
            'UnusedPermissions': len(unused_permissions),
            'UnusedPermissionList': list(unused_permissions),
            'UsagePercentage': (len(used_permissions) / len(all_permissions) * 100) if all_permissions else 0
        }

